writeFile(`business/faq_${lang}.json`, {
	"frequently_asked_questions_about_accepting_bitcoin": "\u03A3\u03C5\u03C7\u03BD\u03AD\u03C2 \u03B5\u03C1\u03C9\u03C4\u03AE\u03C3\u03B5\u03B9\u03C2 \u03C3\u03C7\u03B5\u03C4\u03B9\u03BA\u03AC \u03BC\u03B5 \u03C4\u03B7\u03BD \u03B1\u03C0\u03BF\u03B4\u03BF\u03C7\u03AE Bitcoin",
	"faq_description": "\u0388\u03C7\u03B5\u03C4\u03B5 \u03B5\u03C1\u03C9\u03C4\u03AE\u03C3\u03B5\u03B9\u03C2 \u03C3\u03C7\u03B5\u03C4\u03B9\u03BA\u03AC \u03BC\u03B5 \u03C4\u03B7\u03BD \u03B1\u03C0\u03BF\u03B4\u03BF\u03C7\u03AE \u03C0\u03BB\u03B7\u03C1\u03C9\u03BC\u03CE\u03BD Bitcoin \u03C3\u03C4\u03B7\u03BD \u03B5\u03C0\u03B9\u03C7\u03B5\u03AF\u03C1\u03B7\u03C3\u03AE \u03C3\u03B1\u03C2;",
	"faq_header": "\u0395\u03A7\u0395\u03A4\u0395 \u0395\u03A1\u03A9\u03A4\u0397\u03A3\u0395\u0399\u03A3 \u03A3\u03A7\u0395\u03A4\u0399\u039A\u0391 \u039C\u0395 \u03A4\u0397\u039D \u0391\u03A0\u039F\u0394\u039F\u03A7\u0397 BITCOIN;",
	"faq_s1": "\u03A4\u03B9 \u03B5\u03AF\u03BD\u03B1\u03B9 \u03C4\u03BF Bitcoin;",
	"faq_s1_c1": "\u03A4\u03BF Bitcoin \u03B5\u03AF\u03BD\u03B1\u03B9 \u03B4\u03CD\u03BF \u03C0\u03C1\u03AC\u03B3\u03BC\u03B1\u03C4\u03B1: \u03C8\u03B7\u03C6\u03B9\u03B1\u03BA\u03CC \u03C7\u03C1\u03AE\u03BC\u03B1 \u03BA\u03B1\u03B9 \u03B4\u03AF\u03BA\u03C4\u03C5\u03BF \u03C5\u03C0\u03BF\u03BB\u03BF\u03B3\u03B9\u03C3\u03C4\u03CE\u03BD.",
	"faq_s1_c2": "\u039C\u03C0\u03BF\u03C1\u03B5\u03AF\u03C4\u03B5 \u03BD\u03B1 \u03C3\u03C4\u03B5\u03AF\u03BB\u03B5\u03C4\u03B5 bitcoin (\u03C8\u03B7\u03C6\u03B9\u03B1\u03BA\u03CC \u03C7\u03C1\u03AE\u03BC\u03B1) \u03B1\u03C0\u03B5\u03C5\u03B8\u03B5\u03AF\u03B1\u03C2 \u03C3\u03B5 \u03AC\u03BB\u03BB\u03BF\u03C5\u03C2 \u03B1\u03BD\u03B8\u03C1\u03CE\u03C0\u03BF\u03C5\u03C2 \u03C7\u03C1\u03B7\u03C3\u03B9\u03BC\u03BF\u03C0\u03BF\u03B9\u03CE\u03BD\u03C4\u03B1\u03C2 \u03C4\u03BF \u03B4\u03AF\u03BA\u03C4\u03C5\u03BF Bitcoin.",
	"faq_s1_c3": "\u03A4\u03BF \u03B4\u03AF\u03BA\u03C4\u03C5\u03BF Bitcoin \u03BB\u03B5\u03B9\u03C4\u03BF\u03C5\u03C1\u03B3\u03B5\u03AF \u03C7\u03C9\u03C1\u03AF\u03C2 \u03BC\u03B5\u03C3\u03AC\u03B6\u03BF\u03BD\u03C4\u03B5\u03C2 \u03AE \u03BA\u03B5\u03BD\u03C4\u03C1\u03B9\u03BA\u03AD\u03C2 \u03B1\u03C1\u03C7\u03AD\u03C2, \u03CC\u03C0\u03C9\u03C2 \u03C4\u03C1\u03AC\u03C0\u03B5\u03B6\u03B5\u03C2 \u03AE \u03B5\u03C4\u03B1\u03B9\u03C1\u03B5\u03AF\u03B5\u03C2 \u03C0\u03B9\u03C3\u03C4\u03C9\u03C4\u03B9\u03BA\u03CE\u03BD \u03BA\u03B1\u03C1\u03C4\u03CE\u03BD, \u03CE\u03C3\u03C4\u03B5 \u03BD\u03B1 \u03B1\u03C0\u03BF\u03C6\u03B5\u03CD\u03B3\u03B5\u03C4\u03B5 \u03C4\u03B9\u03C2 \u03C0\u03C1\u03BF\u03BC\u03AE\u03B8\u03B5\u03B9\u03B5\u03C2 \u03C4\u03BF\u03C5\u03C2.",
	"faq_s1_c4": "\u039F\u03B9 \u03C3\u03C5\u03BD\u03B1\u03BB\u03BB\u03B1\u03B3\u03AD\u03C2 Bitcoin \u03B5\u03C0\u03B9\u03C4\u03C5\u03B3\u03C7\u03AC\u03BD\u03BF\u03C5\u03BD \u03BF\u03C1\u03B9\u03C3\u03C4\u03B9\u03BA\u03CC \u03B4\u03B9\u03B1\u03BA\u03B1\u03BD\u03BF\u03BD\u03B9\u03C3\u03BC\u03CC \u03B3\u03C1\u03AE\u03B3\u03BF\u03C1\u03B1 (10 \u03BB\u03B5\u03C0\u03C4\u03AC) \u03BA\u03B1\u03B9 \u03B4\u03B5\u03BD \u03BC\u03C0\u03BF\u03C1\u03BF\u03CD\u03BD \u03C0\u03BF\u03C4\u03AD \u03BD\u03B1 \u03B1\u03BD\u03C4\u03B9\u03C3\u03C4\u03C1\u03B1\u03C6\u03BF\u03CD\u03BD.",
	"faq_s2": "\u03A0\u03CE\u03C2 \u03BC\u03C0\u03BF\u03C1\u03B5\u03AF \u03C4\u03BF Bitcoin \u03BD\u03B1 \u03C9\u03C6\u03B5\u03BB\u03AE\u03C3\u03B5\u03B9 \u03C4\u03B7\u03BD \u03B5\u03C0\u03B9\u03C7\u03B5\u03AF\u03C1\u03B7\u03C3\u03AE \u03BC\u03BF\u03C5;",
	"faq_s2_c1": "\u03A4\u03BF Bitcoin \u03C3\u03B1\u03C2 \u03B5\u03C0\u03B9\u03C4\u03C1\u03AD\u03C0\u03B5\u03B9 \u03BD\u03B1 \u03BB\u03B1\u03BC\u03B2\u03AC\u03BD\u03B5\u03C4\u03B5 \u03C0\u03BB\u03B7\u03C1\u03C9\u03BC\u03AD\u03C2 \u03BC\u03B5 \u03C7\u03B1\u03BC\u03B7\u03BB\u03CC\u03C4\u03B5\u03C1\u03B5\u03C2 \u03C0\u03C1\u03BF\u03BC\u03AE\u03B8\u03B5\u03B9\u03B5\u03C2 \u03BA\u03B1\u03B9 \u03BD\u03B1 \u03B1\u03C0\u03BF\u03BA\u03C4\u03AC\u03C4\u03B5 \u03BD\u03AD\u03BF\u03C5\u03C2 \u03C0\u03B5\u03BB\u03AC\u03C4\u03B5\u03C2.",
	"faq_s2_c2": "\u0397 \u03B1\u03C0\u03BF\u03B4\u03BF\u03C7\u03AE Bitcoin \u03B5\u03AF\u03BD\u03B1\u03B9 \u03B4\u03C9\u03C1\u03B5\u03AC\u03BD \u03BA\u03B1\u03B9 \u03C3\u03B1\u03C2 \u03B5\u03C0\u03B9\u03C4\u03C1\u03AD\u03C0\u03B5\u03B9 \u03BD\u03B1 \u03BA\u03B1\u03C4\u03B1\u03C7\u03C9\u03C1\u03B7\u03B8\u03B5\u03AF\u03C4\u03B5 \u03C3\u03B5 \u03C7\u03AC\u03C1\u03C4\u03B5\u03C2 \u03B5\u03BC\u03C0\u03CC\u03C1\u03C9\u03BD Bitcoin.",
	"faq_s2_c3": "\u0394\u03B5\u03AF\u03C4\u03B5 \u03CC\u03BB\u03BF\u03C5\u03C2 \u03C4\u03BF\u03C5\u03C2 \u03C4\u03C1\u03CC\u03C0\u03BF\u03C5\u03C2 \u03C0\u03BF\u03C5 \u03C4\u03BF Bitcoin \u03B5\u03AF\u03BD\u03B1\u03B9 \u03BA\u03B1\u03BB\u03CC \u03B3\u03B9\u03B1 \u03C4\u03B9\u03C2 \u03B5\u03C0\u03B9\u03C7\u03B5\u03B9\u03C1\u03AE\u03C3\u03B5\u03B9\u03C2.",
	"faq_s3": "\u03A0\u03CE\u03C2 \u03BB\u03B1\u03BC\u03B2\u03AC\u03BD\u03C9 \u03C0\u03BB\u03B7\u03C1\u03C9\u03BC\u03AD\u03C2 Bitcoin;",
	"faq_s3_c1": "\u03A7\u03C1\u03B5\u03B9\u03AC\u03B6\u03B5\u03C3\u03C4\u03B5 \u03BC\u03CC\u03BD\u03BF \u03AD\u03BD\u03B1 \u03B4\u03C9\u03C1\u03B5\u03AC\u03BD \u03C0\u03BF\u03C1\u03C4\u03BF\u03C6\u03CC\u03BB\u03B9 Bitcoin.",
	"faq_s3_c2": "\u039F \u03BF\u03B4\u03B7\u03B3\u03CC\u03C2 \u03C0\u03BF\u03C1\u03C4\u03BF\u03C6\u03BF\u03BB\u03B9\u03BF\u03CD \u03BC\u03B1\u03C2 \u03C3\u03B1\u03C2 \u03B2\u03BF\u03B7\u03B8\u03AC \u03BD\u03B1 \u03BE\u03B5\u03BA\u03B9\u03BD\u03AE\u03C3\u03B5\u03C4\u03B5 \u03B3\u03C1\u03AE\u03B3\u03BF\u03C1\u03B1 \u03BA\u03B1\u03B9 \u03B5\u03CD\u03BA\u03BF\u03BB\u03B1!",
	"faq_s3_c3": "\u0394\u03B5\u03AF\u03C4\u03B5 \u03C4\u03BF\u03BD \u03BF\u03B4\u03B7\u03B3\u03CC \u03C0\u03BF\u03C1\u03C4\u03BF\u03C6\u03BF\u03BB\u03B9\u03BF\u03CD",
	"faq_s4": "\u039C\u03C0\u03BF\u03C1\u03CE \u03BD\u03B1 \u03BC\u03B5\u03C4\u03B1\u03C4\u03C1\u03AD\u03C8\u03C9 \u03C4\u03B9\u03C2 \u03C0\u03BB\u03B7\u03C1\u03C9\u03BC\u03AD\u03C2 Bitcoin \u03C3\u03B5 \u03C4\u03BF\u03C0\u03B9\u03BA\u03CC \u03BD\u03CC\u03BC\u03B9\u03C3\u03BC\u03B1;",
	"faq_s4_c1": "\u039D\u03B1\u03B9! \u039C\u03B5 \u03AD\u03BD\u03B1 \u03C5\u03B2\u03C1\u03B9\u03B4\u03B9\u03BA\u03CC \u03C0\u03BF\u03C1\u03C4\u03BF\u03C6\u03CC\u03BB\u03B9 \u03BC\u03C0\u03BF\u03C1\u03B5\u03AF\u03C4\u03B5 \u03BD\u03B1 \u03BC\u03B5\u03C4\u03B1\u03C4\u03C1\u03AD\u03C0\u03B5\u03C4\u03B5 \u03B1\u03C5\u03C4\u03CC\u03BC\u03B1\u03C4\u03B1 \u03C4\u03B9\u03C2 \u03C0\u03BB\u03B7\u03C1\u03C9\u03BC\u03AD\u03C2 Bitcoin \u03C3\u03B5 \u03C4\u03BF\u03C0\u03B9\u03BA\u03CC \u03BD\u03CC\u03BC\u03B9\u03C3\u03BC\u03B1.",
	"faq_s4_c2": "\u039F \u03BF\u03B4\u03B7\u03B3\u03CC\u03C2 \u03C0\u03BF\u03C1\u03C4\u03BF\u03C6\u03BF\u03BB\u03B9\u03BF\u03CD \u03BC\u03B1\u03C2 \u03C3\u03B1\u03C2 \u03B2\u03BF\u03B7\u03B8\u03AC \u03BD\u03B1 \u03BE\u03B5\u03BA\u03B9\u03BD\u03AE\u03C3\u03B5\u03C4\u03B5 \u03B3\u03C1\u03AE\u03B3\u03BF\u03C1\u03B1.",
	"faq_s4_c3": "\u039C\u03C0\u03BF\u03C1\u03B5\u03AF\u03C4\u03B5 \u03B5\u03C0\u03AF\u03C3\u03B7\u03C2 \u03BD\u03B1 \u03BA\u03C1\u03B1\u03C4\u03AE\u03C3\u03B5\u03C4\u03B5 \u03AD\u03BD\u03B1 \u03BC\u03AD\u03C1\u03BF\u03C2 \u03C4\u03C9\u03BD \u03C0\u03BB\u03B7\u03C1\u03C9\u03BC\u03CE\u03BD \u03C3\u03B5 Bitcoin. \u0397 \u03B1\u03C0\u03BF\u03C4\u03B1\u03BC\u03AF\u03B5\u03C5\u03C3\u03B7 \u03C3\u03B5 Bitcoin \u03AD\u03C7\u03B5\u03B9 \u03C0\u03BF\u03BB\u03BB\u03AC \u03C0\u03BB\u03B5\u03BF\u03BD\u03B5\u03BA\u03C4\u03AE\u03BC\u03B1\u03C4\u03B1:",
	"faq_s4_c4": "\u03A4\u03BF Bitcoin \u03B5\u03AF\u03BD\u03B1\u03B9 \u03AD\u03BD\u03B1 \u03C7\u03C1\u03B7\u03BC\u03B1\u03C4\u03BF\u03C0\u03B9\u03C3\u03C4\u03C9\u03C4\u03B9\u03BA\u03CC \u03C3\u03CD\u03C3\u03C4\u03B7\u03BC\u03B1 \u03C0\u03BB\u03AE\u03C1\u03BF\u03C5\u03C2 \u03B1\u03C0\u03BF\u03B8\u03B5\u03BC\u03B1\u03C4\u03B9\u03BA\u03BF\u03CD.",
	"faq_s4_c5": "\u03A4\u03BF Bitcoin \u03B4\u03B5\u03BD \u03AD\u03C7\u03B5\u03B9 \u03C0\u03BB\u03B7\u03B8\u03C9\u03C1\u03B9\u03C3\u03BC\u03CC.",
	"faq_s4_c6": "\u0391\u03C5\u03C4\u03AC \u03C4\u03B1 \u03C0\u03BB\u03B5\u03BF\u03BD\u03B5\u03BA\u03C4\u03AE\u03BC\u03B1\u03C4\u03B1 \u03BA\u03AC\u03BD\u03BF\u03C5\u03BD \u03C4\u03BF Bitcoin \u03AD\u03BD\u03B1\u03BD \u03B5\u03BE\u03B1\u03B9\u03C1\u03B5\u03C4\u03B9\u03BA\u03CC \u03C4\u03C1\u03CC\u03C0\u03BF \u03B1\u03C0\u03BF\u03B8\u03AE\u03BA\u03B5\u03C5\u03C3\u03B7\u03C2 \u03C7\u03C1\u03B7\u03BC\u03AC\u03C4\u03C9\u03BD \u03BC\u03B1\u03BA\u03C1\u03BF\u03C0\u03C1\u03CC\u03B8\u03B5\u03C3\u03BC\u03B1.",
	"faq_s4_c7": "\u0391\u03BA\u03CC\u03BC\u03B1 \u03BA\u03B9 \u03B1\u03BD \u03B5\u03C0\u03B9\u03BB\u03AD\u03BE\u03B5\u03C4\u03B5 \u03BD\u03B1 \u03BC\u03B5\u03C4\u03B1\u03C4\u03C1\u03AD\u03C8\u03B5\u03C4\u03B5 \u03CC\u03BB\u03B5\u03C2 \u03C4\u03B9\u03C2 \u03C0\u03BB\u03B7\u03C1\u03C9\u03BC\u03AD\u03C2 \u03C3\u03B5 \u03B4\u03BF\u03BB\u03AC\u03C1\u03B9\u03B1, \u03B8\u03B1 \u03B1\u03C0\u03BF\u03BB\u03B1\u03CD\u03C3\u03B5\u03C4\u03B5 \u03C4\u03B1 \u03BF\u03C6\u03AD\u03BB\u03B7 \u03C4\u03C9\u03BD \u03C7\u03B1\u03BC\u03B7\u03BB\u03CC\u03C4\u03B5\u03C1\u03C9\u03BD \u03C0\u03C1\u03BF\u03BC\u03B7\u03B8\u03B5\u03B9\u03CE\u03BD \u03BA\u03B1\u03B9 \u03C0\u03B5\u03C1\u03B9\u03C3\u03C3\u03CC\u03C4\u03B5\u03C1\u03C9\u03BD \u03C0\u03B5\u03BB\u03B1\u03C4\u03CE\u03BD.",
	"faq_s5": "\u039C\u03C0\u03BF\u03C1\u03CE \u03BD\u03B1 \u03BB\u03B1\u03BC\u03B2\u03AC\u03BD\u03C9 \u03C0\u03BB\u03B7\u03C1\u03C9\u03BC\u03AD\u03C2 Bitcoin \u03B1\u03C5\u03C4\u03BF\u03C0\u03C1\u03BF\u03C3\u03CE\u03C0\u03C9\u03C2;",
	"faq_s5_c1": "\u039D\u03B1\u03B9! \u0397 \u03BB\u03AE\u03C8\u03B7 \u03C0\u03BB\u03B7\u03C1\u03C9\u03BC\u03CE\u03BD Bitcoin \u03B1\u03C5\u03C4\u03BF\u03C0\u03C1\u03BF\u03C3\u03CE\u03C0\u03C9\u03C2 \u03B5\u03AF\u03BD\u03B1\u03B9 \u03B5\u03CD\u03BA\u03BF\u03BB\u03B7 \u03BC\u03B5 \u03AD\u03BD\u03B1 \u03C0\u03BF\u03C1\u03C4\u03BF\u03C6\u03CC\u03BB\u03B9 Bitcoin.",
	"faq_s5_c2": "\u039F \u03BF\u03B4\u03B7\u03B3\u03CC\u03C2 \u03C0\u03BF\u03C1\u03C4\u03BF\u03C6\u03BF\u03BB\u03B9\u03BF\u03CD \u03BC\u03B1\u03C2 \u03C3\u03B1\u03C2 \u03B2\u03BF\u03B7\u03B8\u03AC \u03BD\u03B1 \u03B5\u03C0\u03B9\u03BB\u03AD\u03BE\u03B5\u03C4\u03B5 \u03C4\u03BF \u03BA\u03B1\u03BB\u03CD\u03C4\u03B5\u03C1\u03BF.",
	"faq_s5_c3": "\u0394\u03B5\u03AF\u03C4\u03B5 \u03C4\u03BF\u03BD \u03BF\u03B4\u03B7\u03B3\u03CC \u03C0\u03BF\u03C1\u03C4\u03BF\u03C6\u03BF\u03BB\u03B9\u03BF\u03CD",
	"faq_s6": "\u039C\u03C0\u03BF\u03C1\u03CE \u03BD\u03B1 \u03BB\u03B1\u03BC\u03B2\u03AC\u03BD\u03C9 \u03C0\u03BB\u03B7\u03C1\u03C9\u03BC\u03AD\u03C2 Bitcoin \u03B4\u03B9\u03B1\u03B4\u03B9\u03BA\u03C4\u03C5\u03B1\u03BA\u03AC;",
	"faq_s6_c1": "\u039D\u03B1\u03B9! \u0397 \u03BB\u03AE\u03C8\u03B7 \u03C0\u03BB\u03B7\u03C1\u03C9\u03BC\u03CE\u03BD Bitcoin \u03B4\u03B9\u03B1\u03B4\u03B9\u03BA\u03C4\u03C5\u03B1\u03BA\u03AC \u03B5\u03AF\u03BD\u03B1\u03B9 \u03B5\u03CD\u03BA\u03BF\u03BB\u03B7.",
	"faq_s6_c2": "\u039C\u03B5\u03BB\u03B5\u03C4\u03AE\u03C3\u03C4\u03B5 \u03C4\u03BF\u03BD \u03BF\u03B4\u03B7\u03B3\u03CC \u03C0\u03BF\u03C1\u03C4\u03BF\u03C6\u03BF\u03BB\u03B9\u03BF\u03CD \u03BC\u03B1\u03C2 \u03B3\u03B9\u03B1 \u03C0\u03B5\u03C1\u03B9\u03C3\u03C3\u03CC\u03C4\u03B5\u03C1\u03B5\u03C2 \u03C0\u03BB\u03B7\u03C1\u03BF\u03C6\u03BF\u03C1\u03AF\u03B5\u03C2.",
	"faq_s7": "\u03A0\u03CE\u03C2 \u03BC\u03C0\u03BF\u03C1\u03CE \u03BD\u03B1 \u03B5\u03BD\u03B7\u03BC\u03B5\u03C1\u03CE\u03C3\u03C9 \u03C4\u03BF\u03C5\u03C2 \u03C0\u03B5\u03BB\u03AC\u03C4\u03B5\u03C2 \u03CC\u03C4\u03B9 \u03B4\u03AD\u03C7\u03BF\u03BC\u03B1\u03B9 Bitcoin;",
	"faq_s7_c1": "\u03A0\u03C1\u03BF\u03C3\u03C6\u03AD\u03C1\u03BF\u03C5\u03BC\u03B5 \u03B4\u03C9\u03C1\u03B5\u03AC\u03BD \u03B1\u03C5\u03C4\u03BF\u03BA\u03CC\u03BB\u03BB\u03B7\u03C4\u03B1 \u00AB\u03A4\u03BF Bitcoin \u03B3\u03AF\u03BD\u03B5\u03C4\u03B1\u03B9 \u03B4\u03B5\u03BA\u03C4\u03CC \u03B5\u03B4\u03CE\u00BB.",
	"faq_s7_c2": "\u039A\u03AC\u03BD\u03C4\u03B5 \u03BA\u03BB\u03B9\u03BA \u03B5\u03B4\u03CE \u03B3\u03B9\u03B1 \u03BD\u03B1 \u03C0\u03B1\u03C1\u03B1\u03B3\u03B3\u03B5\u03AF\u03BB\u03B5\u03C4\u03B5 \u03B1\u03C5\u03C4\u03BF\u03BA\u03CC\u03BB\u03BB\u03B7\u03C4\u03B1.",
	"faq_s7_c3": "\u039C\u03C0\u03BF\u03C1\u03B5\u03AF\u03C4\u03B5 \u03B5\u03C0\u03AF\u03C3\u03B7\u03C2 \u03BD\u03B1 \u03BA\u03B1\u03C4\u03B1\u03C7\u03C9\u03C1\u03AE\u03C3\u03B5\u03C4\u03B5 \u03B4\u03C9\u03C1\u03B5\u03AC\u03BD \u03C4\u03B7\u03BD \u03B5\u03C0\u03B9\u03C7\u03B5\u03AF\u03C1\u03B7\u03C3\u03AE \u03C3\u03B1\u03C2 \u03C3\u03B5 \u03C7\u03AC\u03C1\u03C4\u03B5\u03C2 \u03B5\u03BC\u03C0\u03CC\u03C1\u03C9\u03BD Bitcoin.",
	"faq_s7_c4": "\u0395\u03B3\u03B3\u03C1\u03B1\u03C6\u03B5\u03AF\u03C4\u03B5 \u03C4\u03CE\u03C1\u03B1.",
	"faq_s8": "\u03A0\u03CE\u03C2 \u03BC\u03C0\u03BF\u03C1\u03CE \u03BD\u03B1 \u03B1\u03C0\u03BF\u03BA\u03C4\u03AE\u03C3\u03C9 \u03C0\u03B5\u03C1\u03B9\u03C3\u03C3\u03CC\u03C4\u03B5\u03C1\u03BF\u03C5\u03C2 \u03C0\u03B5\u03BB\u03AC\u03C4\u03B5\u03C2 \u03B1\u03C0\u03BF\u03B4\u03B5\u03C7\u03CC\u03BC\u03B5\u03BD\u03BF\u03C2 Bitcoin;",
	"faq_s8_c1": "\u0395\u03BA\u03B1\u03C4\u03BF\u03BC\u03BC\u03CD\u03C1\u03B9\u03B1 \u03C7\u03C1\u03AE\u03C3\u03C4\u03B5\u03C2 Bitcoin \u03B8\u03AD\u03BB\u03BF\u03C5\u03BD \u03BD\u03B1 \u03BE\u03BF\u03B4\u03AD\u03C8\u03BF\u03C5\u03BD \u03C4\u03B1 Bitcoin \u03C4\u03BF\u03C5\u03C2.",
	"faq_s8_c2": "\u0391\u03C0\u03BF\u03B4\u03B5\u03C7\u03CC\u03BC\u03B5\u03BD\u03BF\u03B9 Bitcoin, \u03BC\u03C0\u03BF\u03C1\u03B5\u03AF\u03C4\u03B5 \u03BD\u03B1 \u03BA\u03B1\u03C4\u03B1\u03C7\u03C9\u03C1\u03B7\u03B8\u03B5\u03AF\u03C4\u03B5 \u03C3\u03B5 \u03B4\u03C9\u03C1\u03B5\u03AC\u03BD \u03C7\u03AC\u03C1\u03C4\u03B5\u03C2 \u03B5\u03BC\u03C0\u03CC\u03C1\u03C9\u03BD.",
	"faq_s8_c3": "\u0395\u03B3\u03B3\u03C1\u03B1\u03C6\u03B5\u03AF\u03C4\u03B5 \u03C4\u03CE\u03C1\u03B1.",
	"faq_s9": "\u03A0\u03CC\u03C3\u03BF \u03BA\u03BF\u03C3\u03C4\u03AF\u03B6\u03B5\u03B9 \u03B7 \u03B1\u03C0\u03BF\u03B4\u03BF\u03C7\u03AE Bitcoin;",
	"faq_s9_c1": "\u0397 \u03B1\u03C0\u03BF\u03B4\u03BF\u03C7\u03AE Bitcoin \u03B5\u03AF\u03BD\u03B1\u03B9 100% \u03B4\u03C9\u03C1\u03B5\u03AC\u03BD. \u039A\u03B1\u03BD\u03AD\u03BD\u03B1 \u03C3\u03C5\u03BC\u03B2\u03CC\u03BB\u03B1\u03B9\u03BF \u03BA\u03B1\u03B9 \u03BA\u03B1\u03BD\u03AD\u03BD\u03B1 \u03BA\u03C1\u03C5\u03C6\u03AC \u03C4\u03AD\u03BB\u03B7.",
	"faq_s9_c2": "\u039C\u03B5\u03BB\u03B5\u03C4\u03AE\u03C3\u03C4\u03B5 \u03C4\u03BF\u03BD \u03BF\u03B4\u03B7\u03B3\u03CC \u03C0\u03BF\u03C1\u03C4\u03BF\u03C6\u03BF\u03BB\u03B9\u03BF\u03CD \u03BA\u03B1\u03B9 \u03BE\u03B5\u03BA\u03B9\u03BD\u03AE\u03C3\u03C4\u03B5 \u03C3\u03AE\u03BC\u03B5\u03C1\u03B1."
});

