	"bitcoin_business_accounting_guide": "\u039F\u03B4\u03B7\u03B3\u03CC\u03C2 \u03BB\u03BF\u03B3\u03B9\u03C3\u03C4\u03B9\u03BA\u03AE\u03C2 Bitcoin \u03B3\u03B9\u03B1 \u03B5\u03C0\u03B9\u03C7\u03B5\u03B9\u03C1\u03AE\u03C3\u03B5\u03B9\u03C2",
